import RSS from"rss";import{outputFile}from"../common/file-tools.js";import{getGlobalVariables}from"../action/setup-global-variables.js";import*as userServer from"./user.js";export async function update(){const{DUMOGU_Domain:t}=process.env,e=await userServer.getCurrUserSync()||{},r=new RSS({title:e.nickname||"",description:e.synopsis||"",feed_url:`https://${t}/rss.xml`,site_url:`https://${t}`,language:"zh-CN",pubDate:new Date,ttl:60});[{title:"首页",href:"/"},{title:"关于",href:"/about"},{title:"标签",href:"/tags"},{title:"归档",href:"/archive"},{title:"友情链接",href:"/friendly-link"}].forEach(t=>{r.item({title:t.title,url:t.href,date:new Date,description:t.title})});const i=r.xml({indent:!0});await outputFile(getGlobalVariables("rssXmlPath"),i)}